    this.uiKey = uiKey;

    const root = this.containerEl.createDiv({ cls: 'matrix-graph' + (opts.fill ? ' matrix-graph-fill' : '') });
    const bar = root.createDiv({ cls: 'matrix-graph-toolbar' });

